mapper.select:
select t.*, u.user_name as userName, u.phone, u.avatar from tb_coupon_user t,tb_user u where t.user_id = u.user_id
and t.status = #{couponUser.status}
and t.user_id = #{couponUser.userId}
and t.coupon_name like concat("%",#{couponUser.couponName},"%")
and u.phone = #{couponUser.phone}
and u.user_name like concat("%",#{couponUser.userName},"%")
order by create_time desc

select * from tb_coupon_user tc
where tc.min_money <= #{estimateMoney} and tc.status =0 and tc.user_id = #{userId}
order by create_time desc
